using System;using System.Collections.Generic;using System.Linq;using AdvancedMERTools;using AdvancedMERTools.Events.Arguments;using CommandSystem.Commands.RemoteAdmin.Dummies;using Exiled.API.Enums;using Exiled.API.Features;using LabApi.Events.Arguments.ServerEvents;using MEC;using Mirror;using PlayerRoles;using ProjectMER.Events.Arguments;using ProjectMER.Features;using ProjectMER.Features.Objects;using ProjectMER.Features.Serializable.Schematics;using SCP1356Main.API.Events;using SCP1356Main.API.Extensions;using SCP1356Main.API.Schematic.HealthObject;using SCP1356Main.API.Schematic.Radiation;using UnityEngine;using Config = SCP1356Main.Configs.Config;using Random = UnityEngine.Random;using RoundEndedEventArgs = Exiled.Events.EventArgs.Server.RoundEndedEventArgs;namespace SCP1356Main.API.Schematic.Start{    public class SchematicSetup{    public SchematicObject SCP1356Chamber { get; set; }    public SchematicObject SCP1356 { get; set; }    public GameObject SCP1356ChamberHealth { get; set; }    public RadiationRaycast radiation { get; set; }    private static readonly Config Config = Plugin.Singleton.Config;    public void SubEvents()    {        ProjectMER.Events.Handlers.Schematic.SchematicSpawned += OnSchematicSpawned;        Exiled.Events.Handlers.Map.Generated += OnGenerated;       Exiled.Events.Handlers.Server.RoundStarted += OnRoundStart;        Exiled.Events.Handlers.Server.RoundEnded += OnRoundEnded;        SCP1356Main.API.Events.CustomEvents.DamagingSCP1356 += HealthDamaged;    }    public void UnsubEvents()    {        ProjectMER.Events.Handlers.Schematic.SchematicSpawned -= OnSchematicSpawned;        Exiled.Events.Handlers.Map.Generated -= OnGenerated;       Exiled.Events.Handlers.Server.RoundStarted -= OnRoundStart;        Exiled.Events.Handlers.Server.RoundEnded -= OnRoundEnded;        SCP1356Main.API.Events.CustomEvents.DamagingSCP1356 -= HealthDamaged;    }    private bool Cooldown = false;    private bool Cooldown2 = false;    private void HealthDamaged(object obj, DamagingSCP1356 ev)    {            Plugin.Singleton._status.SetHp(ev.SCP1356Hitbox.Health);            if (!Cooldown2)            {                Cooldown2 = true;                Timing.RunCoroutine(CooldownTimer2(2));                Plugin.Singleton._status.SetActivity(Mathf.RoundToInt(UnityEngine.Random.Range(1, ev.Damage)), 2);            }                    if (!Cooldown && Plugin.Singleton.BreachAPI._breachRunning)            {                Cooldown = true;                var ea = Plugin.Singleton.BreachAPI;                var e = Plugin.Singleton.BreachAPI.selected;                var randomItem = e.EventType.RandomItem();                Plugin.Singleton.BreachAPI.HandleEvent(randomItem.EventType, Room.Get(e.RoomType.Value), SCP1356);                Timing.RunCoroutine(CooldownTimer(Random.Range(5f, 15f)));            }            else if (!Cooldown && !Plugin.Singleton.BreachAPI._breachRunning)            {                Cooldown = true;                var e = Enum.GetValues(typeof(Tools.EventTypesScp1356))                    .Cast<Tools.EventTypesScp1356>()                    .ToList().RandomItem();                Plugin.Singleton.BreachAPI.HandleEvent(e, Room.Get(RoomType.Lcz173), SCP1356);                Timing.RunCoroutine(CooldownTimer(Random.Range(5f, 15f)));                            }    }    private IEnumerator<float> CooldownTimer2(float time)    {        yield return Timing.WaitForSeconds(time);        Cooldown2 = false;    }    private IEnumerator<float> CooldownTimer(float time)    {        yield return Timing.WaitForSeconds(time);        Cooldown = false;    }    private void OnSchematicSpawned(SchematicSpawnedEventArgs ev)    {        Log.Debug(ev.Schematic.name);        if (ev.Schematic.name.Contains(Config.SCP1356ChamberName))        {            foreach (Transform transform in ev.Schematic.GetComponentsInChildren<Transform>())            {                if (transform.name.Contains(Config.SCP1356RootName))                {                    Log.Debug(Config.SCP1356RootName + " found");                    if (ObjectSpawner.TrySpawnSchematic(                            "GameObject",                            transform.position,                            transform.rotation,                            new Vector3(1f, 1f, 1f),                            out SchematicObject gameObject))                    {                        SCP1356 = gameObject;                        radiation = new RadiationRaycast(SCP1356.transform);                        radiation.Start();                        Log.Info("Spawned SCP-1356 at Postion: " + SCP1356.Position);                        Plugin.Singleton._status.SetHp(Config.SCP1356Health);                        Plugin.Singleton._status.SetBreachStatus(Plugin.Singleton.Translation.SCP1356ContainmentMessages);                        Plugin.Singleton._status.SetRooms(RoomType.Lcz173, RoomType.Lcz173);                       // DummyDuck(SCP1356); Room.FindParentRoom(SCP1356.gameObject).Type                        SCP1356.gameObject.AddHealth(Config.SCP1356Health, SimpleDeathType.Explode);                    }                    else                    {                        Log.Warn($"Failed to spawn schematic object SCP 1356, GameObject: {transform.name}.");                    }                }            }        }    }    private void OnGenerated()    {    }        private void OnRoundStart()    {                foreach (Tools.TransformData transformData in Config.SchematicData)        {            Vector3 Pos;            Quaternion Rot;            Vector3 Scale;            if (transformData.RoomType.HasValue)            {                Room room = Room.Get(transformData.RoomType.Value);                            Pos = room.WorldPosition(new Vector3(transformData.PosX, transformData.PosY, transformData.PosZ));                Rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(transformData.RotX, transformData.RotY, transformData.RotZ));                Scale = new Vector3(transformData.ScaleX, transformData.ScaleY, transformData.ScaleZ);                if (transformData.SchematicName == Config.SCP1356ChamberName)                {                    Plugin.Singleton.BreachAPI.CurrentRoom = transformData.RoomType.Value;                }            }            else if (transformData.HasRoomName)            {                Pos = GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(transformData.PosX, transformData.PosY, transformData.PosZ), true);                Rot = Quaternion.Euler(GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(transformData.RotX, transformData.RotY, transformData.RotZ), false));                Scale = new Vector3(transformData.ScaleX, transformData.ScaleY, transformData.ScaleZ);            }            else            {                Log.Debug("Weder RoomType noch RoomName");                return;            }                        var schem = ObjectSpawner.SpawnSchematic(transformData.SchematicName, Pos, Rot, Scale);            var deathType = transformData.SimpleDeathType ?? SimpleDeathType.None;            var transformName = transformData.Transform ?? "UseSchematicIfHealthEnabled";            if (transformData.HP <= 0)            {                if (transformData.HP == 0)                {                    Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + Pos);                    Log.Warn($"HealthObject for: {transformData.SchematicName} failed to Spawn: HP can't be Zero!");                    continue;                }                Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + Pos+" and didnt added Health.") ;                continue;            }            if (transformName.Contains("UseSchematicIfHealthEnabled"))            {                schem.gameObject.AddHealth(transformData.HP, deathType);                Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + Pos+" and added Health to Complete Schematic") ;                continue;            }            foreach (Transform transform in schem.GetComponentsInChildren<Transform>())            {                if (transform.name.Contains(transformName))                {                    transform.gameObject.AddHealth(transformData.HP, deathType);                    Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + Pos +" and added Health to Transform named " + transformName);                }            }        }                foreach (Tools.ObjectSpawnData objectSpawnData in Config.PrefabSpawns)        {            Vector3 Pos;            Quaternion Rot;            if (objectSpawnData.RoomType.HasValue)            {                Room room = Room.Get(objectSpawnData.RoomType.Value);                                Pos = room.Transform.TransformPoint(new Vector3(objectSpawnData.PosX, objectSpawnData.PosY, objectSpawnData.PosZ));                Rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(objectSpawnData.RotX, objectSpawnData.RotY, objectSpawnData.RotZ));            }            else if (objectSpawnData.HasRoomName)            {                Pos = GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(objectSpawnData.PosX, objectSpawnData.PosY, objectSpawnData.PosZ), true);                Rot = Quaternion.Euler(GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(objectSpawnData.RotX, objectSpawnData.RotY, objectSpawnData.RotZ), false));            }            else            {                return;            }            if (NetworkClient.prefabs.TryGetValue(objectSpawnData.ObjectId, out var prefab) && prefab != null)            {                Tools.SpawnPrefab(Pos, Rot, objectSpawnData.ObjectId);                Log.Debug("Spawned Prefab: " +  NetworkClient.prefabs[objectSpawnData.ObjectId].name + "at: " + Pos);            }            else            {                Log.Warn("Prefab in Config with ID: " + objectSpawnData.ObjectId + " at Position: " + new Vector3(objectSpawnData.PosX, objectSpawnData.PosY, objectSpawnData.PosZ) + " has an invalid ID!");            }        }        foreach (Tools.RagdollSpawnData ragdollSpawnData in Config.RagdollSpawns)        {            Vector3 Pos;            Quaternion Rot;            if (ragdollSpawnData.RoomType.HasValue)            {                Room room = Room.Get(ragdollSpawnData.RoomType.Value);                Pos = room.Transform.TransformPoint(new Vector3(ragdollSpawnData.PosX, ragdollSpawnData.PosY, ragdollSpawnData.PosZ));                Rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(ragdollSpawnData.RotX, ragdollSpawnData.RotY, ragdollSpawnData.RotZ));            }            else if (ragdollSpawnData.HasRoomName)            {                Pos = GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(ragdollSpawnData.PosX, ragdollSpawnData.PosY, ragdollSpawnData.PosZ), true);                Rot = Quaternion.Euler(GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(ragdollSpawnData.RotX, ragdollSpawnData.RotY, ragdollSpawnData.RotZ), false));            }            else            {                return;            }            Tools.SpawnRagdoll(Pos,Rot, ragdollSpawnData.Name, ragdollSpawnData.DeathReason, ragdollSpawnData.RoleTypeId);            Log.Debug("Spawned Ragdoll: " +  ragdollSpawnData.Name + " at: " + Pos);        }        foreach (Tools.DoorSpawnData doorSpawnData in Config.DoorSpawnData)        {            Vector3 Pos;            Quaternion Rot;            if (doorSpawnData.RoomType.HasValue)            {                Room room = Room.Get(doorSpawnData.RoomType.Value);                Pos = room.Transform.TransformPoint(new Vector3(doorSpawnData.PosX, doorSpawnData.PosY, doorSpawnData.PosZ));                Rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(doorSpawnData.RotX, doorSpawnData.RotY, doorSpawnData.RotZ));                Tools.SpawnDoor(Pos, Rot.eulerAngles, doorSpawnData.DoorSeizable, false);            }            else if (doorSpawnData.HasRoomName)            {                Pos = GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(doorSpawnData.PosX, doorSpawnData.PosY, doorSpawnData.PosZ), true);                Rot = Quaternion.Euler(GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(doorSpawnData.RotX, doorSpawnData.RotY, doorSpawnData.RotZ), false));                Tools.SpawnDoor(Pos, Rot.eulerAngles, doorSpawnData.DoorSeizable, true);            }            else            {                return;            }            Log.Debug("Spawned Door: " +  doorSpawnData.DoorSeizable.ToString() + " at: " + Pos);        }        foreach (Tools.PickupSpawnData pickupSpawn in Config.PickupSpawns)        {            Vector3 Pos;            Quaternion Rot;            if (pickupSpawn.RoomType.HasValue)            {                Room room = Room.Get(pickupSpawn.RoomType.Value);                Pos = room.Transform.TransformPoint(new Vector3(pickupSpawn.PosX, pickupSpawn.PosY, pickupSpawn.PosZ));                Rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(pickupSpawn.RotX, pickupSpawn.RotY, pickupSpawn.RotZ));            }            else if (pickupSpawn.HasRoomName)            {                Pos = GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(pickupSpawn.PosX, pickupSpawn.PosY, pickupSpawn.PosZ), true);                Rot = Quaternion.Euler(GetChamberSetuped.GetWorldData(Plugin.Singleton.GetChamberSetuped.SCP1356Chamber,                    new Vector3(pickupSpawn.RotX, pickupSpawn.RotY, pickupSpawn.RotZ), false));            }            else            {                return;            }            Tools.SpawnPickup(Pos, Rot, pickupSpawn.ItemType);            Log.Debug("Spawned Pickup: " +  pickupSpawn.ItemType.ToString() + " at: " + Pos);        }    }        private void OnRoundEnded(RoundEndedEventArgs obj)    {            }    public Npc SCP1356DummyNpc { get; set; }    private void DummyDuck(SchematicObject scp1356)    {        if (!Config.SCP1356Dummy)            return;        SCP1356DummyNpc = Npc.Spawn(Config.SCP1356DummyName, Config.SCP1356DummyRole, scp1356.Position);        Timing.CallDelayed(1f, () =>        {            if (SCP1356DummyNpc == null) return;            SCP1356DummyNpc.IsGodModeEnabled = true;            SCP1356DummyNpc.IsNoclipEnabled = true;            SCP1356DummyNpc.Scale = new Vector3(0.1f, 0.1f, 0.1f);            SCP1356DummyNpc.Rotation = scp1356.Rotation;            HidePlayer(SCP1356DummyNpc);        });    }        public static void HidePlayer(Player target)    {        foreach (var ply in Player.List)        {            if (ply.Connection == null) continue;            ply.Connection.Send(new ObjectDestroyMessage            {                netId = target.NetId            });        }    }}}